import type { Graph } from '@antv/x6'
import { graphToDocument, loadDocument } from '../document/graphAdapter'
import {
  pageState, drawingDocument, insertDrawingPage, duplicateDrawingPage, removeDrawingPage,
  renameDrawingPage, moveDrawingPage, sortDrawingPages, clearDrawingPages,
  parseDrawingDocument, type DrawingDocument, type DrawingState, type DrawingPage,
} from '../document/drawing'

export type DrawingSessionEvent = 'change' | 'page' | 'load' | 'readonly'
export type DrawingSession = ReturnType<typeof createDrawingSession>
type HistoryEntry = { before: DrawingState; after: DrawingState }
type Options = { firstPageName?: string; onError?(error: Error): void }

/** One stable X6 surface; semantic snapshots follow native committed history batches. */
export function createDrawingSession(graph: Graph, initial: unknown, options: Options = {}) {
  let data = pageState(initial, options.firstPageName), readonly = false, disposed = false,
    restoring = false, generation = 0
  const past: HistoryEntry[] = [], future: HistoryEntry[] = []
  const listeners = new Set<(event: DrawingSessionEvent) => void>()
  const original = { undo: graph.undo, redo: graph.redo, canUndo: graph.canUndo, canRedo: graph.canRedo }
  const current = () => data.pages.find((page) => page.id === data.activeId)!
  const assertLive = () => { if (disposed) throw Error('Drawing session is closed') }
  const editable = () => { assertLive(); if (readonly) throw Error('Drawing is read-only') }
  const notify = (event: DrawingSessionEvent) => { for (const listener of listeners) listener(event) }
  function capture() {
    assertLive()
    const { tx, ty } = graph.translate()
    const model = graphToDocument(graph, data.metadata, { zoom: graph.zoom(), pan: { x: tx, y: ty } })
    const page = current()
    const graphData = JSON.stringify(page.graph) === JSON.stringify(model.graph) ? page.graph : model.graph
    data = { ...data, pages: data.pages.map((p) => p.id === page.id
      ? { ...page, graph: graphData, viewport: model.viewport } : p) }
    return data
  }
  function restore(next: DrawingState, force = false) {
    const old = current(), page = next.pages.find((p) => p.id === next.activeId)!
    const changedPage = old.id !== page.id
    const replace = force || changedPage || old.graph !== page.graph
    if (replace) {
      const selected = changedPage ? [] : graph.getSelectedCells().map((cell) => cell.id)
      restoring = true
      try {
        const model = loadDocument(graph, {
          format: 'frade-draw', version: 1, metadata: next.metadata, graph: page.graph,
          ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
        })
        next = { ...next, pages: next.pages.map((p) => p.id === page.id ? { ...p, graph: model.graph } : p) }
        if (selected.length) graph.select(selected.flatMap((id) => {
          const cell = graph.getCellById(id)
          return cell ? [cell] : []
        }))
      } finally { restoring = false }
      generation++
    }
    data = next
    return replace
  }
  function mutate(operation: (state: DrawingState) => DrawingState) {
    editable()
    const before = capture(), next = operation(before)
    if (next === before) return
    const pageChanged = restore(next)
    past.push({ before, after: data }); future.length = 0
    if (pageChanged) notify('page')
    notify('change')
  }
  function committed() {
    if (restoring || disposed) return
    // X6 records a provisional connection before both semantic terminals exist.
    // It is not a drawing command yet; flush/navigation still validate and reject it.
    if (graph.getEdges().some((edge) => !edge.getSourceCell() || !edge.getTargetCell())) return
    const before = data
    try {
      capture()
      if (current().graph === before.pages.find((p) => p.id === before.activeId)!.graph) return
      past.push({ before, after: data }); future.length = 0
      notify('change')
    } catch (error) {
      if (!options.onError) throw error
      options.onError(error instanceof Error ? error : Error(String(error)))
    }
  }
  function undo() {
    editable()
    const entry = past.at(-1)
    if (!entry) return
    const changedPage = restore({ ...entry.before, metadata: data.metadata })
    past.pop(); future.push(entry)
    if (changedPage) notify('page')
    notify('change')
  }
  function redo() {
    editable()
    const entry = future.at(-1)
    if (!entry) return
    const changedPage = restore({ ...entry.after, metadata: data.metadata })
    future.pop(); past.push(entry)
    if (changedPage) notify('page')
    notify('change')
  }
  restore(data, true)
  capture()
  graph.on('history:add', committed)
  graph.undo = () => { undo(); return graph }
  graph.redo = () => { redo(); return graph }
  graph.canUndo = () => !readonly && past.length > 0
  graph.canRedo = () => !readonly && future.length > 0
  const empty = (id: string, name: string): DrawingPage => ({ id, name, graph: { nodes: [], edges: [] } })
  return {
    view: () => ({ activeId: data.activeId, pages: data.pages.map(({ id, name }) => ({ id, name })),
      canUndo: !readonly && past.length > 0, canRedo: !readonly && future.length > 0, readOnly: readonly }),
    get generation() { return generation },
    get restoring() { return restoring },
    subscribe(listener: (event: DrawingSessionEvent) => void) {
      assertLive(); listeners.add(listener); return () => { listeners.delete(listener) }
    },
    snapshot(): DrawingDocument { return parseDrawingDocument(drawingDocument(capture())) },
    load(value: unknown) {
      assertLive()
      const next = pageState(value, options.firstPageName)
      restore(next, true); capture(); past.length = 0; future.length = 0
      notify('load')
      return drawingDocument(data)
    },
    select(id: string) {
      assertLive()
      if (id === data.activeId) return
      if (!data.pages.some((page) => page.id === id)) throw Error('Page no longer exists')
      capture(); restore({ ...data, activeId: id }); notify('page')
    },
    insert: (id: string, name: string) => mutate((state) => insertDrawingPage(state, empty(id, name))),
    duplicate: (source: string, id: string, name: string) =>
      mutate((state) => duplicateDrawingPage(state, source, id, name)),
    rename: (id: string, name: string) => mutate((state) => renameDrawingPage(state, id, name)),
    remove: (id: string, replacementId: string, name: string) =>
      mutate((state) => removeDrawingPage(state, id, empty(replacementId, name))),
    move: (id: string, index: number) => mutate((state) => moveDrawingPage(state, id, index)),
    sort: (locale: string) => mutate((state) => sortDrawingPages(state, locale)),
    clear: (id: string, name: string) => mutate((state) => clearDrawingPages(state, empty(id, name))),
    setName(name: string) {
      editable()
      if (!name.trim()) throw Error('Document name must not be empty.')
      data = { ...data, metadata: { ...data.metadata, name: name.trim() } }; notify('change')
    },
    extract(id: string, documentId: string) {
      capture()
      const page = data.pages.find((p) => p.id === id)
      if (!page) throw Error('Page no longer exists')
      return parseDrawingDocument({ format: 'frade-draw', version: 1,
        metadata: { id: documentId, name: page.name }, graph: page.graph, viewport: page.viewport })
    },
    setReadOnly(value: boolean) {
      assertLive()
      if (readonly !== value) { readonly = value; notify('readonly') }
    },
    undo, redo,
    dispose() {
      if (disposed) return
      disposed = true; graph.off('history:add', committed); listeners.clear()
      Object.assign(graph, original)
    },
  }
}
import { deserializeDrawingDocument, serializeDrawingDocument, type DrawingDocument } from '../document/drawing'
const prefix='frade.page-transfer/',fragment='#frade-page='
const lifetime=60000
/** One-shot same-origin application transfer; never a write-back document reference. */
export function receivePageTransfer():DrawingDocument|undefined {
  if(!location.hash.startsWith(fragment))return
  const key=prefix+decodeURIComponent(location.hash.slice(fragment.length))
  const raw=localStorage.getItem(key)
  localStorage.removeItem(key)
  history.replaceState(null,'',location.pathname+location.search)
  if(!raw)throw Error('Не удалось открыть копию страницы')
  const value=JSON.parse(raw)
  if(typeof value.created!=='number'||Date.now()-value.created>lifetime||typeof value.document!=='string')
    throw Error('Истекло время открытия копии страницы')
  return deserializeDrawingDocument(value.document)
}
export function openTransferredPage(document:DrawingDocument) {
  const id=crypto.randomUUID(),key=prefix+id
  localStorage.setItem(key,JSON.stringify({created:Date.now(),document:serializeDrawingDocument(document)}))
  const child=window.open('about:blank','_blank')
  if(!child){localStorage.removeItem(key);throw Error('Разрешите открытие нового окна для страницы')}
  child.opener=null
  const url=new URL(location.href);url.hash=fragment.slice(1)+encodeURIComponent(id)
  try{child.location.href=url.toString()}catch(error){localStorage.removeItem(key);child.close();throw error}
  setTimeout(()=>localStorage.removeItem(key),lifetime)
}

import { parseDocument, type DiagramDocument } from './schema'

export type DrawingPage = {
  id: string
  name: string
  graph: DiagramDocument['graph']
  viewport?: DiagramDocument['viewport']
}
export type MultipageDocument = {
  format: 'frade-draw'
  version: 2
  metadata: DiagramDocument['metadata']
  pages: DrawingPage[]
}
export type DrawingDocument = DiagramDocument | MultipageDocument
export type DrawingState = {
  version: 1 | 2
  metadata: DiagramDocument['metadata']
  pages: DrawingPage[]
  activeId: string
}

function record(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value))
    throw Error('Invalid drawing structure')
  return value as Record<string, unknown>
}
function name(value: unknown, message: string): string {
  if (typeof value !== 'string' || !value.trim()) throw Error(message)
  return value
}

/** Validate every graph before any editor/session replacement. The v1 API stays unchanged. */
export function parseDrawingDocument(value: unknown): DrawingDocument {
  const input = record(value)
  if (input.version !== 2) return parseDocument(value)
  if (input.format !== 'frade-draw') throw Error('Unsupported document format')
  const metadata = parseDocument({
    format: 'frade-draw', version: 1, metadata: input.metadata,
    graph: { nodes: [], edges: [] },
  }).metadata
  if (!Array.isArray(input.pages) || !input.pages.length) throw Error('Drawing needs a page')
  const ids = new Set<string>()
  const pages = input.pages.map((value) => {
    const page = record(value), id = name(page.id, 'Invalid page ID')
    if (ids.has(id)) throw Error('Duplicate page ID')
    ids.add(id)
    const parsed = parseDocument({
      format: 'frade-draw', version: 1, metadata, graph: page.graph,
      ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
    })
    return {
      id, name: name(page.name, 'Invalid page name'), graph: parsed.graph,
      ...(parsed.viewport === undefined ? {} : { viewport: parsed.viewport }),
    }
  })
  return { format: 'frade-draw', version: 2, metadata, pages }
}
export const serializeDrawingDocument = (value: DrawingDocument) =>
  JSON.stringify(parseDrawingDocument(value), null, 2)
export const deserializeDrawingDocument = (json: string) => parseDrawingDocument(JSON.parse(json))

export function pageState(value: unknown, firstName = 'Страница-1'): DrawingState {
  const document = parseDrawingDocument(value)
  const pages = document.version === 2 ? document.pages : [{
    id: document.metadata.id + '/page-1', name: firstName, graph: document.graph,
    ...(document.viewport === undefined ? {} : { viewport: document.viewport }),
  }]
  return { version: document.version, metadata: document.metadata, pages, activeId: pages[0].id }
}
export function drawingDocument(state: DrawingState): DrawingDocument {
  if (state.version === 2)
    return { format: 'frade-draw', version: 2, metadata: state.metadata, pages: state.pages }
  const page = state.pages[0]
  return {
    format: 'frade-draw', version: 1, metadata: state.metadata, graph: page.graph,
    ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
  }
}
export function semanticDrawing(value: DrawingDocument) {
  const parsed = parseDrawingDocument(value)
  if (parsed.version === 1) {
    const { viewport: _viewport, ...content } = parsed
    return content
  }
  return { ...parsed, pages: parsed.pages.map(({ viewport: _viewport, ...page }) => page) }
}
/** Semantic dirty key: object formatting/order and navigation are not diagram edits. */
export function drawingContentKey(json: string): string {
  return JSON.stringify(semanticDrawing(deserializeDrawingDocument(json)), (_key, value) =>
    value && typeof value === 'object' && !Array.isArray(value)
      ? Object.fromEntries(Object.keys(value).sort().map((key) => [key, value[key]])) : value)
}
function pageIndex(state: DrawingState, id: string) {
  const index = state.pages.findIndex((page) => page.id === id)
  if (index < 0) throw Error('Page no longer exists')
  return index
}
function newPage(state: DrawingState, page: DrawingPage) {
  if (state.pages.some((current) => current.id === page.id)) throw Error('Duplicate page ID')
  const parsed = parseDrawingDocument({ format: 'frade-draw', version: 2,
    metadata: state.metadata, pages: [page] }) as MultipageDocument
  return parsed.pages[0]
}
export function nextPageName(pages: DrawingPage[], numbered: (index: number) => string) {
  const names = new Set(pages.map((page) => page.name))
  let index = pages.length + 1
  while (names.has(numbered(index))) index++
  return numbered(index)
}
export function insertDrawingPage(state: DrawingState, value: DrawingPage): DrawingState {
  const page = newPage(state, value)
  return { ...state, version: 2, pages: [...state.pages, page], activeId: page.id }
}
export function duplicateDrawingPage(
  state: DrawingState, sourceId: string, id: string, copyName: string,
): DrawingState {
  const index = pageIndex(state, sourceId), source = state.pages[index]
  const graph = structuredClone(source.graph)
  const mapped = new Map(graph.nodes.map((node) => [node.id, id + '/' + node.id]))
  for (const node of graph.nodes) node.id = mapped.get(node.id)!
  for (const edge of graph.edges) {
    edge.id = id + '/' + edge.id
    edge.source.nodeId = mapped.get(edge.source.nodeId)!
    edge.target.nodeId = mapped.get(edge.target.nodeId)!
  }
  const page = newPage(state, { id, name: copyName, graph })
  const pages = state.pages.slice()
  pages.splice(index + 1, 0, page)
  return { ...state, version: 2, pages, activeId: id }
}
export function renameDrawingPage(state: DrawingState, id: string, value: string): DrawingState {
  const index = pageIndex(state, id)
  if (!value.trim() || state.pages[index].name === value) return state
  return { ...state, version: 2,
    pages: state.pages.map((page, i) => i === index ? { ...page, name: value } : page) }
}
export function clearDrawingPages(state: DrawingState, replacement: DrawingPage): DrawingState {
  const page = newPage(state, replacement)
  return { ...state, version: 2, pages: [page], activeId: page.id }
}
export function removeDrawingPage(
  state: DrawingState, id: string, replacement: DrawingPage,
): DrawingState {
  const index = pageIndex(state, id)
  if (state.pages.length === 1) return clearDrawingPages(state, replacement)
  const pages = state.pages.filter((page) => page.id !== id)
  return { ...state, version: 2, pages,
    activeId: state.activeId === id ? pages[Math.min(index, pages.length - 1)].id : state.activeId }
}
export function moveDrawingPage(state: DrawingState, id: string, destination: number): DrawingState {
  const index = pageIndex(state, id)
  if (!Number.isInteger(destination) || destination < 0 || destination >= state.pages.length)
    throw Error('Invalid page position')
  if (index === destination) return state
  const pages = state.pages.slice(), page = pages.splice(index, 1)[0]
  pages.splice(destination, 0, page)
  return { ...state, version: 2, pages }
}
export function sortDrawingPages(state: DrawingState, locale: string): DrawingState {
  const compare = new Intl.Collator(locale, { numeric: true, sensitivity: 'base' })
  const pages = state.pages.slice().sort((a, b) => compare.compare(a.name, b.name))
  return pages.every((page, i) => page === state.pages[i]) ? state : { ...state, version: 2, pages }
}
