import { installSegmentAdapter } from '../segment-editing/x6Adapter'
import { createDrawingSession, type DrawingSession } from './drawingSession'
import { PageStrip } from './PageStrip'
import { receivePageTransfer, openTransferredPage } from './pageTransfer'
import { pageLabels } from './generated/drawio-pages'

export type DiagramEditorProps = {
  embedded?: boolean
  onGraphReady?: (graph: Graph, session: DrawingSession) => void | (() => void)
  requestDocumentName?: (currentName: string) => string | null | Promise<string | null>
  initialDocument?: unknown
  readOnly?: boolean
  locale?: keyof typeof pageLabels
}
const newMetadata = () => ({ id: crypto.randomUUID(), name: 'diagram' })
let number = 1
export function DiagramEditor({ onGraphReady, requestDocumentName, embedded, initialDocument, readOnly=false, locale='ru' }: DiagramEditorProps) {
  const host = useRef<HTMLDivElement>(null)
  const graph = useRef<Graph | null>(null)
  const initial = useRef(initialDocument), controller = useRef<DrawingSession>()
  const [session,setSession] = useState<DrawingSession>()
  const [,refresh] = useState(0)
  const idPrefix = 'frade-drawing-' + useId().replaceAll(':','')
  const readGeneration = useRef(0)
  const [selected, setSelected] = useState<string | null>(null)
  const [gridVisible, setGridVisible] = useState(true)
  const [error, setError] = useState('')
  const [opening, setOpening] = useState(false)
  const fileInput = useRef<HTMLInputElement>(null)
  useEffect(() => {
    const generationRef = readGeneration
    if (!host.current) return
    const instance = createGraph(host.current)
    graph.current = instance
    const empty: DiagramDocument = {format:'frade-draw',version:1,metadata:newMetadata(),graph:{nodes:[],edges:[]}}
    let model=initial.current
    if(model===undefined)try{model=receivePageTransfer()}catch(error){setError(error instanceof Error?error.message:String(error))}
    let drawing:DrawingSession
    try{drawing=createDrawingSession(instance,model??empty,{firstPageName:pageLabels[locale].pageWithNumber.replace('{1}','1'),onError:error=>setError(error.message)})}
    catch(error){setError(error instanceof Error?error.message:String(error));drawing=createDrawingSession(instance,empty)}
    drawing.setReadOnly(readOnly)
    controller.current=drawing
    const unsubscribe=drawing.subscribe(()=>refresh(value=>value+1))
    setSession(drawing)
    const resize = () => instance.resize?.(host.current!.clientWidth, host.current!.clientHeight)
    resize()
    const observer = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(resize)
    observer?.observe(host.current)
    const disposeHostIntegration = onGraphReady?.(instance,drawing)
    instance.on('selection:changed', ({ selected }) => {
      instance.getEdges().forEach((edge) => edge.removeTools())
      const cell = selected[0]
      if (cell?.isEdge()) installSegmentAdapter(cell)
      setSelected(cell?.id ?? null)
    })
    return () => {
      generationRef.current++
      observer?.disconnect()
      disposeHostIntegration?.()
      unsubscribe()
      drawing.dispose()
      instance.dispose()
      graph.current = null
      controller.current=undefined
    }
  }, [onGraphReady])
  useLayoutEffect(()=>{
    const instance=graph.current
    if(!instance||!session)return
    session.setReadOnly(readOnly||opening)
    const previous=instance.options.interacting
    if(readOnly||opening){instance.options.interacting=false;instance.disableKeyboard();instance.cleanSelection();instance.clearTransformWidgets()}
    else instance.enableKeyboard()
    return()=>{instance.options.interacting=previous}
  },[readOnly,opening,session])
  const add = (shape: DiagramShape) => {
    const instance = graph.current
    if (!instance || readOnly || opening) return
    let id: string
    do {
      id = 'node-' + number++
    } while (instance.getCellById(id))
    instance.addNode(
      nodeToCell({
        id,
        shape,
        x: 120 + number * 12,
        y: 120 + number * 12,
        width: 150,
        height: 72,
        label: shape === 'text' ? 'Text' : 'New shape',
      }),
    )
  }
  const remove = () => {
    if (selected && !readOnly && !opening) graph.current?.removeCell(selected)
  }
  const zoom = (amount: number) => graph.current?.zoom(amount)
  const toggleGrid = () => {
    const next = !gridVisible
    setGridVisible(next)
    if (next) graph.current?.showGrid()
    else graph.current?.hideGrid()
  }
  const save = async (saveAs = false) => {
    const instance = graph.current, drawing=controller.current
    if (!instance || !drawing || readOnly) return
    const generation = readGeneration.current
    try {
      const next = drawing.snapshot().metadata
      if (saveAs) {
        const name = requestDocumentName
          ? await requestDocumentName(next.name)
          : window.prompt('Document name', next.name)
        if (generation !== readGeneration.current || graph.current !== instance) return
        if (name === null) return
        if (!name.trim()) {
          setError('Document name must not be empty.')
          return
        }
        drawing.setName(name.trim())
      }
      downloadDocument(drawing.snapshot())
      setError('')
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Could not save the document.')
    }
  }
  const createNew = () => {
    const instance = graph.current
    if (!instance || readOnly) return
    readGeneration.current++
    setOpening(false)
    const next = newMetadata()
    controller.current?.load({
      format: 'frade-draw',
      version: 1,
      metadata: next,
      graph: { nodes: [], edges: [] },
    })
    setSelected(null)
    setError('')
  }
  const open = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0],
      instance = graph.current
    event.target.value = ''
    if (!file || !instance) return
    const generation = ++readGeneration.current
    setOpening(true)
    try {
      const model = await readDocument(file)
      if (generation !== readGeneration.current || graph.current !== instance) return
      controller.current?.load(model)
      setSelected(null)
      setError('')
    } catch (error) {
      if (generation === readGeneration.current)
        setError(error instanceof Error ? error.message : 'Could not open the document.')
    } finally {
      if (generation === readGeneration.current) setOpening(false)
    }
  }
  return (
    <main className="frade-drawing-editor">
      <header>
        <strong>Frade Draw</strong>
        {!embedded && (
          <>
            <button onClick={createNew} disabled={readOnly}>New</button>
            <button onClick={() => save()} disabled={opening||readOnly}>
              Save
            </button>
            <button onClick={() => save(true)} disabled={opening||readOnly}>
              Save As
            </button>
            <button onClick={() => fileInput.current?.click()}>Open</button>
            <input
              ref={fileInput}
              type="file"
              accept="application/json,.json"
              aria-label="Open diagram"
              hidden
              onChange={open}
            />
          </>
        )}
        <button onClick={remove} disabled={!selected || opening || readOnly}>
          Delete
        </button>
        <button onClick={() => graph.current?.undo()} disabled={opening || readOnly || !session?.view().canUndo}>
          Undo
        </button>
        <button onClick={() => graph.current?.redo()} disabled={opening || readOnly || !session?.view().canRedo}>
          Redo
        </button>
        <button onClick={() => zoom(0.1)}>Zoom +</button>
        <button onClick={() => zoom(-0.1)}>Zoom −</button>
        <button onClick={() => graph.current?.zoomToFit({ padding: 30 })}>Fit</button>
        <button onClick={toggleGrid}>Grid</button>
        <button onClick={() => graph.current?.exportSVG('diagram.svg')}>SVG</button>
        <button onClick={() => graph.current?.exportPNG('diagram.png')}>PNG</button>
      </header>
      <aside>
        {diagramShapes.map((shape) => (
          <button key={shape} disabled={opening||readOnly} onClick={() => add(shape)}>
            {shape}
          </button>
        ))}
        {error && <p role="alert">{error}</p>}
      </aside>
      <div className="canvas" ref={host} id={idPrefix+'-canvas'} role="tabpanel"
        aria-labelledby={session?idPrefix+'-page-'+encodeURIComponent(session.view().activeId):undefined}
        style={opening ? { pointerEvents: 'none' } : undefined} />
      {session&&<PageStrip session={session} locale={locale} idPrefix={idPrefix} embedded={embedded}
        onError={setError} onOpenPage={id=>{openTransferredPage(session.extract(id,crypto.randomUUID()))}}/>}
    </main>
  )
}
import { useEffect, useLayoutEffect, useRef, useState, type KeyboardEvent } from 'react'
import { pageLabels } from './generated/drawio-pages'
import type { DrawingSession } from './drawingSession'
import { nextPageName } from '../document/drawing'

type Locale = keyof typeof pageLabels
type MenuState = { kind: 'pages' | 'page' | 'current' | 'move'; id: string; x: number; y: number; opener: HTMLElement; parent?:MenuState }
type Item = { label: string; action(opener:HTMLElement): void; disabled?: boolean; checked?: boolean; submenu?: boolean; dialog?:boolean } | null
export function PageStrip({session,locale='ru',idPrefix,onError,onOpenPage,embedded}: {
  session:DrawingSession;locale?:Locale;idPrefix:string;onError(message:string):void;
  onOpenPage(id:string):void;embedded?:boolean
}) {
  const view=session.view(),t=pageLabels[locale],tabs=useRef(new Map<string,HTMLSpanElement>())
  const [focused,setFocused]=useState(view.activeId),[menu,setMenu]=useState<MenuState>(),
    [rename,setRename]=useState<{id:string;name:string;opener:HTMLElement}>(),
    [overflow,setOverflow]=useState(false),[atStart,setAtStart]=useState(true),[atEnd,setAtEnd]=useState(false),
    [dragId,setDragId]=useState<string>()
  const scroller=useRef<HTMLDivElement>(null),footer=useRef<HTMLElement>(null)
  const dragging=useRef<{id:string;generation:number}>()
  const renameRef=useRef(rename)
  useLayoutEffect(()=>{renameRef.current=rename},[rename])
  const focus=(id:string)=>{setFocused(id);requestAnimationFrame(()=>tabs.current.get(id)?.focus())}
  const run=(action:()=>void)=>{try{action()}catch(error){onError(error instanceof Error?error.message:String(error))}}
  const closeMenu=()=>{let first=menu;while(first?.parent)first=first.parent;const opener=first?.opener;setMenu(undefined);requestAnimationFrame(()=>opener?.isConnected&&opener.focus())}
  useEffect(()=>session.subscribe(event=>{
    if(event==='page'||event==='load'){setMenu(undefined);setRename(undefined);setFocused(session.view().activeId)}
    if(event==='load'||(event==='readonly'&&session.view().readOnly)){dragging.current=undefined;setDragId(undefined);const pending=renameRef.current;setRename(undefined);if(pending)requestAnimationFrame(()=>tabs.current.get(session.view().activeId)?.focus())}
  }),[session])
  const checkOverflow=()=>{
    const node=scroller.current
    if(!node)return
    setOverflow(node.scrollWidth>node.clientWidth)
    setAtStart(node.scrollLeft<=0);setAtEnd(node.scrollLeft+node.clientWidth>=node.scrollWidth-1)
  }
  useLayoutEffect(()=>{
    checkOverflow()
    const observer=typeof ResizeObserver==='undefined'?undefined:new ResizeObserver(checkOverflow)
    if(footer.current)observer?.observe(footer.current)
    return()=>observer?.disconnect()
  },[view.pages.length,overflow])
  useLayoutEffect(()=>{
    tabs.current.get(view.activeId)?.scrollIntoView({block:'nearest',inline:'nearest'})
    checkOverflow()
  },[view.activeId,view.pages.map(p=>p.name).join('\0')])
  const activate=(id:string)=>run(()=>{session.select(id);setFocused(id);setMenu(undefined)})
  const numbered=(n:number)=>t.pageWithNumber.replace('{1}',String(n))
  const insert=()=>run(()=>{
    const state=session.view()
    const name=nextPageName(state.pages.map(p=>({...p,graph:{nodes:[],edges:[]}})),numbered)
    session.insert(crypto.randomUUID(),name)
  })
  function openPageMenu(id:string,opener:HTMLElement,x?:number,y?:number){
    run(()=>{
      session.select(id)
      const box=opener.getBoundingClientRect()
      setMenu({kind:'page',id,opener,x:x??box.left,y:y??box.top})
    })
  }
  function tabKey(event:KeyboardEvent<HTMLSpanElement>,id:string){
    const index=view.pages.findIndex(p=>p.id===id)
    let target:number|undefined
    if(event.key==='ArrowRight')target=(index+1)%view.pages.length
    if(event.key==='ArrowLeft')target=(index+view.pages.length-1)%view.pages.length
    if(event.key==='Home')target=0
    if(event.key==='End')target=view.pages.length-1
    if(target!==undefined){event.preventDefault();focus(view.pages[target].id)}
    else if(event.key==='Enter'||event.key===' '){event.preventDefault();activate(id)}
    else if(event.key==='ContextMenu'||(event.shiftKey&&event.key==='F10')){event.preventDefault();openPageMenu(id,event.currentTarget)}
  }
  function submenu(parent:MenuState,kind:MenuState['kind'],opener:HTMLElement,id=parent.id){
    const b=opener.getBoundingClientRect();setMenu({kind,id,opener,x:b.right,y:b.top,parent})
  }
  function menuItems(info:MenuState):Item[]{
    const page=view.pages.find(p=>p.id===info.id)
    if(info.kind==='pages')return [
    {label:t.insertPage,disabled:view.readOnly,action:insert},null,
    ...view.pages.map(p=>({label:p.name,checked:p.id===view.activeId,
      submenu:p.id===view.activeId&&!view.readOnly,
      action:(opener:HTMLElement)=>{if(p.id===view.activeId&&!view.readOnly)submenu(info,'current',opener,p.id);else{session.select(p.id);focus(p.id)}}})),null,
    {label:t.sortPages,disabled:view.readOnly||view.pages.length<2,action:()=>session.sort(locale)},
    {label:t.deleteAll,disabled:view.readOnly,action:()=>session.clear(crypto.randomUUID(),numbered(1))},
  ]
    if(info.kind==='move')return view.pages.flatMap((p,i)=>p.id===info.id?[]:[{label:p.name,action:()=>session.move(info.id,i)}])
    if(!page)return []
    const duplicate={label:t.duplicateIt.replace('{1}',t.page),disabled:view.readOnly,
      action:()=>session.duplicate(page.id,crypto.randomUUID(),t.copyOf.replace('{1}',page.name))}
    const move={label:t.move,disabled:view.readOnly,submenu:true,action:(opener:HTMLElement)=>submenu(info,'move',opener)}
    const remove={label:t.removeIt.replace('{1}',t.page),disabled:view.readOnly,
      action:()=>session.remove(page.id,crypto.randomUUID(),numbered(1))}
    const renameItem={label:t.renameIt.replace('{1}',t.page)+'...',disabled:view.readOnly,dialog:true,
      action:()=>setRename({id:page.id,name:page.name,opener:tabs.current.get(page.id)!})}
    const separate={label:t.openInNewWindow,action:()=>onOpenPage(page.id)}
    if(info.kind==='current')return [renameItem,remove,...(view.pages.length>1?[move,null]:[]),duplicate,...(!embedded?[separate]:[])]
    return [
    ...(!embedded?[separate,null]:[]),duplicate,null,...(view.pages.length>1?[move]:[]),remove,renameItem,
  ]
  }
  const menus:MenuState[]=[]
  for(let node=menu;node;node=node.parent)menus.unshift(node)
  const control=(label:string,glyph:string,action:(opener:HTMLElement)=>void,disabled=false,hasMenu=false)=>
    <div role="button" className={'geTab geControlTab'+(disabled?' mxDisabled':'')}
      tabIndex={disabled?-1:0} title={label} aria-label={label} aria-disabled={disabled}
      aria-haspopup={hasMenu?'menu':undefined} aria-expanded={hasMenu?menus[0]?.kind==='pages':undefined}
      onClick={event=>{if(!disabled)action(event.currentTarget)}}
      onKeyDown={event=>{if(!disabled&&(event.key==='Enter'||event.key===' ')){event.preventDefault();action(event.currentTarget)}}}>
      <div className={'geButton frade-page-glyph frade-page-'+glyph} aria-hidden="true" />
    </div>
  return <footer ref={footer} className="frade-page-strip" data-frade-page-surface="1" data-frade-editor="light"
    onKeyDownCapture={event=>{if(event.key==='Escape'&&dragging.current){dragging.current=undefined;setDragId(undefined);event.preventDefault()}}}>
    <div className="geTabContainer geTabItem">
      {control(t.insertPage,'insert',insert,view.readOnly)}
      {control(t.pages,'menu',opener=>{const b=opener.getBoundingClientRect();setMenu({kind:'pages',id:view.activeId,opener,x:b.left,y:b.top})},false,true)}
      <div className="geTabScroller" ref={scroller} role="tablist" aria-label={t.pages} onScroll={checkOverflow}>
        {view.pages.map((p,index)=><div key={p.id} className={'geTab gePageTab'+(p.id===view.activeId?' geActivePage':'')+(dragId===p.id?' gePageTabDragPlaceholder':'')}
          title={p.name+' ('+p.id+') ['+(index+1)+']'} draggable={!view.readOnly}
          onClick={()=>activate(p.id)}
          onDoubleClick={event=>{if(!view.readOnly)setRename({id:p.id,name:p.name,opener:tabs.current.get(p.id)??event.currentTarget})}}
          onContextMenu={event=>{event.preventDefault();openPageMenu(p.id,tabs.current.get(p.id)!,event.clientX,event.clientY)}}
          onDragStart={event=>{if(view.readOnly){event.preventDefault();return}dragging.current={id:p.id,generation:session.generation};event.dataTransfer.setData('application/x-frade-page',p.id);event.dataTransfer.effectAllowed='move';setDragId(p.id)}}
          onDragOver={event=>{if(dragging.current&&!view.readOnly){event.preventDefault();event.dataTransfer.dropEffect='move'}}}
          onDrop={event=>{event.preventDefault();const drag=dragging.current;dragging.current=undefined;setDragId(undefined);if(drag&&!view.readOnly&&drag.generation===session.generation)run(()=>session.move(drag.id,index))}}
          onDragEnd={()=>{dragging.current=undefined;setDragId(undefined)}}>
          <span ref={node=>{if(node)tabs.current.set(p.id,node);else tabs.current.delete(p.id)}}
            id={idPrefix+'-page-'+encodeURIComponent(p.id)} role="tab" aria-selected={p.id===view.activeId}
            aria-controls={idPrefix+'-canvas'} tabIndex={focused===p.id?0:-1} className="frade-page-label"
            onKeyDown={event=>tabKey(event,p.id)}>{p.name}</span>
          <div role="button" className="geButton frade-page-glyph frade-page-options" tabIndex={p.id===view.activeId?0:-1}
            aria-label={p.name+' — '+t.options} aria-haspopup="menu" aria-expanded={menus[0]?.id===p.id&&menus[0]?.kind==='page'}
            onClick={event=>{event.stopPropagation();openPageMenu(p.id,event.currentTarget)}}
            onKeyDown={event=>{if(['Enter',' ','ArrowDown'].includes(event.key)){event.preventDefault();event.stopPropagation();openPageMenu(p.id,event.currentTarget)}}}/>
        </div>)}
      </div>
      {overflow&&<>
        {control(locale==='ru'?'Предыдущая страница':'Previous Page','left',()=>scroller.current?.scrollBy({left:-160}),atStart)}
        {control(locale==='ru'?'Следующая страница':'Next Page','right',()=>scroller.current?.scrollBy({left:160}),atEnd)}
      </>}
      <a className="frade-page-attribution" href="https://github.com/jgraph/drawio" target="_blank" rel="noreferrer" title="jgraph/drawio" aria-label="jgraph/drawio"><span aria-hidden="true"/></a>
    </div>
    {menus.map((info,index)=><PageMenu key={info.kind+info.id} owner={idPrefix} expandedOpener={menus[index+1]?.opener} menu={info} items={menuItems(info)} close={closeMenu}
      back={()=>{if(info.parent){setMenu(info.parent);requestAnimationFrame(()=>info.opener.focus())}else closeMenu()}}
      hover={(item,opener)=>{if(item.submenu&&!item.disabled)run(()=>item.action(opener));else if(info!==menu)setMenu(info)}}
      execute={(item,opener)=>{if(item.disabled)return;run(()=>item.action(opener));if(!item.submenu){setMenu(undefined);if(!item.dialog)focus(session.view().activeId)}}}/>)}
    {rename&&<RenamePage name={rename.name} title={t.rename} cancel={t.cancel} readOnly={view.readOnly}
      close={()=>{setRename(undefined);requestAnimationFrame(()=>rename.opener.isConnected&&rename.opener.focus())}}
      confirm={value=>{run(()=>session.rename(rename.id,value));setRename(undefined);focus(rename.id)}}/>}
  </footer>
}

function PageMenu({owner,expandedOpener,menu,items,close,back,hover:onHover,execute}:{owner:string;expandedOpener?:HTMLElement;menu:MenuState;items:Item[];close():void;back():void;hover(item:NonNullable<Item>,opener:HTMLElement):void;execute(item:NonNullable<Item>,opener:HTMLElement):void}){
  const root=useRef<HTMLDivElement>(null),rows=useRef<(HTMLTableRowElement|null)[]>([])
  const [position,setPosition]=useState({left:menu.x,top:menu.y}),[hover,setHover]=useState(-1)
  useLayoutEffect(()=>{
    const node=root.current!
    const b=node.getBoundingClientRect()
    setPosition({left:Math.max(4,menu.parent&&menu.x+b.width>innerWidth-4?menu.opener.getBoundingClientRect().left-b.width:Math.min(menu.x,innerWidth-b.width-4)),top:Math.max(4,menu.parent?Math.min(menu.y,innerHeight-b.height-4):menu.y-b.height)})
    rows.current.find((row,i)=>row&&!items[i]?.disabled)?.focus()
  },[])
  useEffect(()=>{
    const outside=(event:PointerEvent)=>{if((event.target as Element).closest('[data-frade-page-menu-owner]')?.getAttribute('data-frade-page-menu-owner')!==owner)close()}
    document.addEventListener('pointerdown',outside,true)
    return()=>document.removeEventListener('pointerdown',outside,true)
  },[close])
  const key=(event:KeyboardEvent)=>{
    const enabled=items.flatMap((item,i)=>item&&!item.disabled?[i]:[]),current=rows.current.indexOf(document.activeElement as HTMLTableRowElement),index=enabled.indexOf(current)
    let next:number|undefined
    if(event.key==='ArrowDown')next=enabled[(index+1)%enabled.length]
    if(event.key==='ArrowUp')next=enabled[(index+enabled.length-1)%enabled.length]
    if(event.key==='Home')next=enabled[0]
    if(event.key==='End')next=enabled.at(-1)
    if(next!==undefined){event.preventDefault();rows.current[next]?.focus();setHover(next)}
    if(event.key==='Escape'||event.key==='Tab'||event.key==='ArrowLeft'){event.preventDefault();event.stopPropagation();if(event.key==='ArrowLeft')back();else close()}
    const item=items[current]
    if(item&&((event.key==='Enter'||event.key===' ')||(event.key==='ArrowRight'&&item.submenu))){event.preventDefault();execute(item,rows.current[current]!)}
  }
  return <div ref={root} className="frade-page-overlay" data-frade-page-menu-owner={owner} data-frade-page-surface="1" data-frade-editor="light" style={position} onKeyDown={key}>
    <div className="mxPopupMenu frade-page-popup" role="menu">
      <table className="mxPopupMenu" role="presentation"><tbody>
        {items.map((item,i)=>item?<tr key={i} ref={row=>{rows.current[i]=row}} role="menuitem" tabIndex={-1}
          aria-label={item.label} aria-disabled={!!item.disabled} aria-haspopup={item.submenu?'menu':undefined}
          aria-expanded={item.submenu?expandedOpener===rows.current[i]:undefined}
          className={(hover===i?'mxPopupMenuItemHover':'mxPopupMenuItem')+(item.disabled?' mxDisabled':'')}
          onMouseEnter={event=>{if(!item.disabled){setHover(i);onHover(item,event.currentTarget)}}} onMouseLeave={()=>setHover(-1)}
          onClick={event=>execute(item,event.currentTarget)} onFocus={()=>setHover(i)}>
          <td className="mxPopupMenuIcon"/>
          <td className="mxPopupMenuItem">{item.label}{item.checked&&<div className="frade-page-check" aria-hidden="true"/>}</td>
          <td className="mxPopupMenuItem frade-page-submenu-cell">{item.submenu&&<div className="frade-page-submenu-glyph" aria-hidden="true"/>}</td>
        </tr>:<tr key={i} role="separator"><td className="mxPopupMenuIcon frade-page-separator-icon"/><td colSpan={2} className="frade-page-separator-rule"><hr/></td></tr>)}
      </tbody></table>
    </div>
  </div>
}
function RenamePage({name,title,cancel,readOnly,confirm,close}:{name:string;title:string;cancel:string;readOnly:boolean;confirm(value:string):void;close():void}){
  const dialog=useRef<HTMLDialogElement>(null),input=useRef<HTMLInputElement>(null)
  const[value,setValue]=useState(name)
  useLayoutEffect(()=>{const node=dialog.current!;node.showModal();input.current?.select();return()=>{if(node.open)node.close()}},[])
  return <div data-frade-page-surface="1" data-frade-editor="light">
    <dialog ref={dialog} className="geDialog frade-page-dialog" aria-label={title} onCancel={event=>{event.preventDefault();close()}}>
      <form onSubmit={event=>{event.preventDefault();if(!readOnly&&value.trim())confirm(value)}}>
        <input ref={input} type="text" aria-label="Имя страницы" value={value} onChange={event=>setValue(event.target.value)} disabled={readOnly}/>
        <div className="frade-page-dialog-actions"><button type="button" className="geBtn" onClick={close}>{cancel}</button>
          <button type="submit" className="geBtn gePrimaryBtn" disabled={readOnly||!value.trim()}>{title}</button></div>
      </form>
    </dialog>
  </div>
}

export type Point = { x: number; y: number }
export const diagramShapes = ['rect', 'rounded-rect', 'ellipse', 'diamond', 'text'] as const
export type DiagramShape = (typeof diagramShapes)[number]
export const styleKeys = [
  'fill',
  'stroke',
  'strokeWidth',
  'strokeDasharray',
  'opacity',
  'fillOpacity',
  'strokeOpacity',
  'rx',
  'ry',
  'fontSize',
  'fontFamily',
  'fontWeight',
  'fontStyle',
  'textAnchor',
] as const
export type DiagramStyle = Partial<Record<(typeof styleKeys)[number], string | number>>
export type Attachment = (
  { mode: 'floating'; nodeId: string } | { mode: 'fixed'; nodeId: string; portId: string }
) & { offset?: Point }
export type DiagramPort = Point & { id: string }
export type RepositoryNodeReference = { objectId: string; sourceId?: string }
export type DiagramShadow = { color: string; opacity: number; dx: number; dy: number; blur: number }
export type DiagramNode = {
  shadow?: DiagramShadow
  repositoryRef?: RepositoryNodeReference
  id: string
  shape: DiagramShape
  x: number
  y: number
  width: number
  height: number
  label: string
  style?: DiagramStyle
  labelStyle?: DiagramStyle
  ports?: DiagramPort[]
}
export type DiagramEdge = {
  labelPosition?: { distance: number; offset: Point }
  bundle?: { kind: 'empty'; integrationFlowRefs?: { repositoryId: string; objectId: string }[] }
  id: string
  source: Attachment
  target: Attachment
  constraints?: Array<{ axis: 'x' | 'y'; coordinate: number; order: number }>
  vertices?: Point[]
  style?: DiagramStyle
  router?: 'normal' | 'manhattan'
  targetMarker?: { name: 'classic' | 'block' | 'diamond' | 'circle'; size: number } | null
}
export interface DiagramDocument {
  format: 'frade-draw'
  version: 1
  metadata: { id: string; name: string }
  graph: { nodes: DiagramNode[]; edges: DiagramEdge[] }
  viewport?: { zoom: number; pan: Point }
}

function record(value: unknown, message: string): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(message)
  return value as Record<string, unknown>
}
function text(value: unknown, message: string): string {
  if (typeof value !== 'string' || !value.trim()) throw new Error(message)
  return value
}
function finite(value: unknown, message: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error(message)
  return value
}
function point(value: unknown, message: string): Point {
  const p = record(value, message)
  return { x: finite(p.x, message), y: finite(p.y, message) }
}
function style(value: unknown): DiagramStyle | undefined {
  if (value === undefined) return undefined
  const input = record(value, 'Invalid style'),
    result: DiagramStyle = {}
  for (const [key, val] of Object.entries(input)) {
    if (
      !(styleKeys as readonly string[]).includes(key) ||
      !(
        (typeof val === 'number' && Number.isFinite(val)) ||
        (typeof val === 'string' &&
          val.length <= 200 &&
          !/[<>\\]|url\s*\(|expression\s*\(/i.test(val))
      )
    ) {
      throw new Error('Invalid style')
    }
    result[key as (typeof styleKeys)[number]] = val as string | number
  }
  return result
}
function attachment(value: unknown): Attachment {
  const input = record(value, 'Invalid edge')
  const nodeId = text(input.nodeId, 'Invalid edge')
  let result: Attachment
  if (input.mode === 'floating') result = { mode: 'floating', nodeId }
  else if (input.mode === 'fixed')
    result = { mode: 'fixed', nodeId, portId: text(input.portId, 'Invalid edge') }
  else throw new Error('Invalid edge')
  if (input.offset !== undefined) result.offset = point(input.offset, 'Invalid terminal offset')
  return result
}

export function parseDocument(value: unknown): DiagramDocument {
  const input = record(value, 'Document must be an object')
  if (input.format !== 'frade-draw' && input.format !== 'frade-designer')
    throw new Error('Unsupported document format')
  if (input.version !== 1) throw new Error('Unsupported document version')
  const metadata = record(input.metadata, 'Invalid document structure')
  const graph = record(input.graph, 'Invalid document structure')
  if (!Array.isArray(graph.nodes) || !Array.isArray(graph.edges))
    throw new Error('Invalid document structure')
  const ids = new Set<string>()
  const cellId = (value: unknown) => {
    const id = text(value, 'Invalid cell ID')
    if (ids.has(id)) throw new Error('Duplicate cell ID')
    ids.add(id)
    return id
  }
  const nodes: DiagramNode[] = graph.nodes.map((value) => {
    const n = record(value, 'Invalid node')
    const id = cellId(n.id),
      pos = point(n, 'Invalid node')
    const width = finite(n.width, 'Invalid node'),
      height = finite(n.height, 'Invalid node')
    if (
      width <= 0 ||
      height <= 0 ||
      !diagramShapes.includes(n.shape as DiagramShape) ||
      typeof n.label !== 'string'
    )
      throw new Error('Invalid node')
    const node: DiagramNode = {
      id,
      shape: n.shape as DiagramShape,
      ...pos,
      width,
      height,
      label: n.label,
    }
    if (n.repositoryRef !== undefined) {
      const ref = record(n.repositoryRef, 'Invalid repository reference')
      if (Object.keys(ref).some((k) => !['objectId', 'sourceId'].includes(k)))
        throw Error('Invalid repository reference')
      node.repositoryRef = {
        objectId: text(ref.objectId, 'Invalid repository reference'),
        ...(ref.sourceId !== undefined
          ? { sourceId: text(ref.sourceId, 'Invalid source reference') }
          : {}),
      }
    }
    if (n.shadow !== undefined) {
      const shadow = record(n.shadow, 'Invalid shadow')
      if (
        Object.keys(shadow).some((k) => !['color', 'opacity', 'dx', 'dy', 'blur'].includes(k)) ||
        typeof shadow.color !== 'string' ||
        !/^#[0-9a-f]{6}$/i.test(shadow.color)
      )
        throw Error('Invalid shadow')
      const opacity = finite(shadow.opacity, 'Invalid shadow'),
        dx = finite(shadow.dx, 'Invalid shadow'),
        dy = finite(shadow.dy, 'Invalid shadow'),
        blur = finite(shadow.blur, 'Invalid shadow')
      if (
        opacity < 0 ||
        opacity > 100 ||
        Math.abs(dx) > 100 ||
        Math.abs(dy) > 100 ||
        blur < 0 ||
        blur > 100
      )
        throw Error('Invalid shadow')
      node.shadow = { color: shadow.color, opacity, dx, dy, blur }
    }
    if (n.style !== undefined) node.style = style(n.style)
    if (n.labelStyle !== undefined) node.labelStyle = style(n.labelStyle)
    if (n.ports !== undefined) {
      if (!Array.isArray(n.ports)) throw new Error('Invalid ports')
      const portIds = new Set<string>()
      node.ports = n.ports.map((value) => {
        const port = record(value, 'Invalid port'),
          id = text(port.id, 'Invalid port')
        if (portIds.has(id)) throw new Error('Duplicate port ID')
        portIds.add(id)
        return { id, ...point(port, 'Invalid port') }
      })
    }
    return node
  })
  const nodeIds = new Map(nodes.map((node) => [node.id, node]))
  const edges: DiagramEdge[] = graph.edges.map((value) => {
    const e = record(value, 'Invalid edge')
    const edge: DiagramEdge = {
      id: cellId(e.id),
      source: attachment(e.source),
      target: attachment(e.target),
    }
    if (e.labelPosition !== undefined) {
      const position = record(e.labelPosition, 'Invalid label position')
      edge.labelPosition = {
        distance: finite(position.distance, 'Invalid label distance'),
        offset: point(position.offset, 'Invalid label offset'),
      }
    }
    if (e.bundle !== undefined) {
      const bundle = record(e.bundle, 'Invalid bundle')
      if (
        bundle.kind !== 'empty' ||
        Object.keys(bundle).some((k) => !['kind', 'integrationFlowRefs'].includes(k))
      )
        throw Error('Unsupported bundle')
      edge.bundle = { kind: 'empty' }
      if (bundle.integrationFlowRefs !== undefined) {
        if (
          !Array.isArray(bundle.integrationFlowRefs) ||
          bundle.integrationFlowRefs.length > 100000
        )
          throw Error('Invalid bundle references')
        const seen = new Set<string>()
        edge.bundle.integrationFlowRefs = bundle.integrationFlowRefs.map((value) => {
          const ref = record(value, 'Invalid bundle reference')
          if (Object.keys(ref).length !== 2) throw Error('Invalid bundle reference')
          const canonical = {
              repositoryId: text(ref.repositoryId, 'Invalid bundle reference'),
              objectId: text(ref.objectId, 'Invalid bundle reference'),
            },
            key = JSON.stringify([canonical.repositoryId, canonical.objectId])
          if (seen.has(key)) throw Error('Duplicate bundle reference')
          seen.add(key)
          return canonical
        })
      }
    }
    for (const terminal of [edge.source, edge.target]) {
      const node = nodeIds.get(terminal.nodeId)
      if (!node) throw new Error('Dangling node reference')
      if (
        terminal.mode === 'fixed' &&
        node.ports &&
        !node.ports.some((p) => p.id === terminal.portId)
      )
        throw new Error('Dangling port reference')
    }
    if (e.constraints !== undefined) {
      if (!Array.isArray(e.constraints)) throw new Error('Invalid edge constraints')
      const orders = new Set<number>()
      edge.constraints = e.constraints.map((value) => {
        const c = record(value, 'Invalid edge constraints')
        const order = finite(c.order, 'Invalid edge constraints')
        if (
          (c.axis !== 'x' && c.axis !== 'y') ||
          !Number.isInteger(order) ||
          order < 0 ||
          orders.has(order)
        )
          throw new Error('Invalid edge constraints')
        orders.add(order)
        return { axis: c.axis, coordinate: finite(c.coordinate, 'Invalid edge constraints'), order }
      })
    }
    if (e.vertices !== undefined) {
      if (!Array.isArray(e.vertices)) throw new Error('Invalid vertices')
      edge.vertices = e.vertices.map((p) => point(p, 'Invalid vertex'))
    }
    if (e.style !== undefined) edge.style = style(e.style)
    if (e.router !== undefined) {
      if (e.router !== 'normal' && e.router !== 'manhattan') throw new Error('Invalid router')
      edge.router = e.router
    }
    if (e.targetMarker === null) edge.targetMarker = null
    else if (e.targetMarker !== undefined) {
      const marker = record(e.targetMarker, 'Invalid marker')
      if (!['classic', 'block', 'diamond', 'circle'].includes(String(marker.name)))
        throw new Error('Invalid marker')
      const size = finite(marker.size, 'Invalid marker')
      if (size <= 0) throw new Error('Invalid marker')
      edge.targetMarker = { name: marker.name as 'classic', size }
    }
    return edge
  })
  const document: DiagramDocument = {
    format: 'frade-draw',
    version: 1,
    metadata: {
      id: text(metadata.id, 'Invalid document structure'),
      name: text(metadata.name, 'Invalid document structure'),
    },
    graph: { nodes, edges },
  }
  if (input.viewport !== undefined) {
    const v = record(input.viewport, 'Invalid viewport'),
      zoom = finite(v.zoom, 'Invalid viewport')
    if (zoom <= 0) throw new Error('Invalid viewport')
    document.viewport = { zoom, pan: point(v.pan, 'Invalid viewport') }
  }
  return document
}
import type { Graph } from '@antv/x6'
import {
  diagramShapes,
  parseDocument,
  styleKeys,
  type Attachment,
  type DiagramDocument,
  type DiagramEdge,
  type DiagramNode,
  type DiagramShape,
  type DiagramStyle,
  type Point,
} from './schema'

type NodeLike = {
  id: string
  shape?: string
  getPosition(): Point
  getSize(): { width: number; height: number }
  attr?(name: string): unknown
  getProp?(name: string): unknown
  getPorts?(): Array<{ id?: string; group?: string }>
  getPortsPosition?(group: string): Record<string, { position: Point }>
}
type EdgeLike = {
  id: string
  attr?(name: string): unknown
  getSource?(): unknown
  getTarget?(): unknown
  getProp?(name: string): unknown
  getVertices?(): Point[]
}
type GraphLike = { getNodes(): NodeLike[]; getEdges(): EdgeLike[] }
function attachment(value: unknown): Attachment {
  const terminal = value as {
    cell: string
    port?: string
    anchor?: { name?: string; args?: { dx?: number; dy?: number } }
    connectionPoint?: { name?: string }
  }
  const result: Attachment = terminal.port
    ? { mode: 'fixed', nodeId: terminal.cell, portId: terminal.port }
    : { mode: 'floating', nodeId: terminal.cell }
  if (terminal.anchor?.name === 'nodeCenter' && terminal.connectionPoint?.name === 'anchor')
    result.offset = { x: terminal.anchor.args?.dx ?? 0, y: terminal.anchor.args?.dy ?? 0 }
  return result
}
function readStyle(
  cell: { attr?(name: string): unknown },
  selector: string,
): DiagramStyle | undefined {
  const style: DiagramStyle = {}
  for (const key of styleKeys) {
    const value = cell.attr?.(selector + '/' + key)
    if (typeof value === 'string' || typeof value === 'number') style[key] = value
  }
  return Object.keys(style).length ? style : undefined
}
function semanticShape(node: NodeLike): DiagramShape {
  const saved = node.getProp?.('diagramShape')
  if (diagramShapes.includes(saved as DiagramShape)) return saved as DiagramShape
  if (node.shape === 'polygon') return 'diamond'
  if (node.shape === 'rect' && Number(node.attr?.('body/rx')) > 0) return 'rounded-rect'
  if (
    node.shape === 'rect' &&
    node.attr?.('body/fill') === 'transparent' &&
    node.attr?.('body/stroke') === 'none'
  )
    return 'text'
  return diagramShapes.includes(node.shape as DiagramShape) ? (node.shape as DiagramShape) : 'rect'
}
export function graphToDocument(
  graph: GraphLike,
  metadata: DiagramDocument['metadata'],
  viewport?: DiagramDocument['viewport'],
): DiagramDocument {
  const nodes: DiagramNode[] = graph.getNodes().map((node) => {
    const ports = node.getPorts?.().map((port) => ({
      id: port.id!,
      ...(node.getPortsPosition?.(port.group ?? '')[port.id!]?.position ?? {
        x: node.getSize().width,
        y: node.getSize().height / 2,
      }),
    }))
    return {
      id: node.id,
      ...(node.getProp?.('repositoryRef')
        ? { repositoryRef: node.getProp('repositoryRef') as DiagramNode['repositoryRef'] }
        : {}),
      ...(node.getProp?.('diagramShadow')
        ? { shadow: node.getProp('diagramShadow') as DiagramNode['shadow'] }
        : {}),
      shape: semanticShape(node),
      ...node.getPosition(),
      ...node.getSize(),
      label: String(node.attr?.('label/text') ?? ''),
      style: readStyle(node, 'body'),
      labelStyle: readStyle(node, 'label'),
      ...(ports?.length ? { ports } : {}),
    }
  })
  const edges: DiagramEdge[] = graph.getEdges().map((edge) => {
    const rawRouter = edge.getProp?.('router') as { name?: string } | undefined
    const rawMarker = edge.attr?.('line/targetMarker') as DiagramEdge['targetMarker'] | undefined
    const result: DiagramEdge = {
      ...(edge.getProp?.('repositoryBundle')
        ? { bundle: edge.getProp('repositoryBundle') as DiagramEdge['bundle'] }
        : {}),
      id: edge.id,
      source: attachment(edge.getSource!()),
      target: attachment(edge.getTarget!()),
      constraints: canonicalConstraints(edge.getProp?.('constraints') ?? edge.getVertices?.()),
      style: readStyle(edge, 'line'),
    }
    const label = edge.getProp?.('labels') as
      Array<{ position?: DiagramEdge['labelPosition'] }> | undefined
    const automaticPosition = edge.getProp?.(
      'bundleAutoLabelPosition',
    ) as DiagramEdge['labelPosition']
    if (
      edge.getProp?.('repositoryBundle') &&
      label?.[0]?.position &&
      (!automaticPosition ||
        label[0].position.distance !== automaticPosition.distance ||
        label[0].position.offset.x !== automaticPosition.offset.x ||
        label[0].position.offset.y !== automaticPosition.offset.y)
    )
      result.labelPosition = {
        distance: label[0].position.distance,
        offset: { ...label[0].position.offset },
      }
    // Keep complete vertices; reducing them to alternating coordinates loses information.
    if (edge.getVertices) result.vertices = edge.getVertices().map(({ x, y }) => ({ x, y }))
    if (rawRouter?.name === 'orth') result.router = 'manhattan'
    if (rawRouter?.name === 'normal' || rawRouter?.name === 'manhattan')
      result.router = rawRouter.name
    if (rawMarker === null) result.targetMarker = null
    else if (rawMarker && typeof rawMarker === 'object')
      result.targetMarker = { name: rawMarker.name, size: rawMarker.size ?? 8 }
    return result
  })
  return {
    format: 'frade-draw',
    version: 1,
    metadata: { ...metadata },
    graph: { nodes, edges },
    viewport,
  }
}
function canonicalConstraints(value: unknown): DiagramEdge['constraints'] {
  if (!Array.isArray(value)) return undefined
  return value.flatMap((point, order) => {
    if (!point || typeof point !== 'object') return []
    const candidate = point as { x?: unknown; y?: unknown; axis?: unknown; coordinate?: unknown }
    if (
      (candidate.axis === 'x' || candidate.axis === 'y') &&
      typeof candidate.coordinate === 'number'
    )
      return [{ axis: candidate.axis, coordinate: candidate.coordinate, order }]
    if (typeof candidate.x === 'number' && typeof candidate.y === 'number')
      return [
        {
          axis: order % 2 === 0 ? 'x' : ('y' as const),
          coordinate: order % 2 === 0 ? candidate.x : candidate.y,
          order,
        },
      ]
    return []
  })
}

export function nodeToCell(node: DiagramNode): Parameters<Graph['createNode']>[0] {
  const shadow = node.shadow
  const filter = shadow
    ? 'drop-shadow(' +
      shadow.dx +
      'px ' +
      shadow.dy +
      'px ' +
      shadow.blur +
      'px ' +
      shadow.color +
      Math.round(shadow.opacity * 2.55)
        .toString(16)
        .padStart(2, '0') +
      ')'
    : 'none'
  const body = {
    style: { filter },
    magnet: true,
    fill: '#ffffff',
    stroke: '#334155',
    strokeWidth: 1.5,
    ...(node.shape === 'rounded-rect' ? { rx: 12, ry: 12 } : {}),
    ...(node.shape === 'diamond' ? { refPoints: '0,10 10,0 20,10 10,20' } : {}),
    ...(node.shape === 'text' ? { fill: 'transparent', stroke: 'none' } : {}),
    ...node.style,
  }
  return {
    id: node.id,
    shape: node.shape === 'diamond' ? 'polygon' : node.shape === 'ellipse' ? 'ellipse' : 'rect',
    diagramShape: node.shape,
    ...(shadow ? { diagramShadow: { ...shadow } } : {}),
    ...(node.repositoryRef ? { repositoryRef: { ...node.repositoryRef } } : {}),
    x: node.x,
    y: node.y,
    width: node.width,
    height: node.height,
    attrs: { body, label: { text: node.label, ...node.labelStyle } },
    ...(node.ports?.length
      ? {
          ports: {
            groups: {
              document: { position: 'absolute', attrs: { circle: { r: 4, magnet: true } } },
            },
            items: node.ports.map(({ id, x, y }) => ({ id, group: 'document', args: { x, y } })),
          },
        }
      : {}),
  }
}
function terminalToCell(terminal: Attachment) {
  return {
    cell: terminal.nodeId,
    ...(terminal.mode === 'fixed' ? { port: terminal.portId } : {}),
    ...(terminal.offset
      ? {
          anchor: { name: 'nodeCenter', args: { dx: terminal.offset.x, dy: terminal.offset.y } },
          connectionPoint: { name: 'anchor' },
        }
      : {}),
  }
}
function legacyVertices(edge: DiagramEdge, nodes: DiagramNode[]): Point[] | undefined {
  if (!edge.constraints?.length) return undefined
  const source = nodes.find((n) => n.id === edge.source.nodeId)!
  let cursor = { x: source.x + source.width / 2, y: source.y + source.height / 2 }
  return [...edge.constraints]
    .sort((a, b) => a.order - b.order)
    .map(({ axis, coordinate }) => {
      cursor = { ...cursor, [axis]: coordinate }
      return { ...cursor }
    })
}
export function loadDocument(graph: Graph, value: unknown): DiagramDocument {
  const document = parseDocument(value)
  // Older files only stored port identities; provide deterministic fallback positions.
  for (const edge of document.graph.edges)
    for (const terminal of [edge.source, edge.target]) {
      if (terminal.mode === 'fixed') {
        const node = document.graph.nodes.find((n) => n.id === terminal.nodeId)!
        node.ports ??= []
        if (!node.ports.some((p) => p.id === terminal.portId))
          node.ports.push({ id: terminal.portId, x: node.width, y: node.height / 2 })
      }
    }
  const nodes = document.graph.nodes.map((node) => graph.createNode(nodeToCell(node)))
  const edges = document.graph.edges.map((edge) => {
    const vertices = edge.vertices ?? legacyVertices(edge, document.graph.nodes)
    return graph.createEdge({
      id: edge.id,
      ...(edge.bundle ? { repositoryBundle: { ...edge.bundle } } : {}),
      ...(edge.labelPosition
        ? { labels: [{ position: { ...edge.labelPosition, options: { absoluteOffset: true } } }] }
        : {}),
      source: terminalToCell(edge.source),
      target: terminalToCell(edge.target),
      vertices,
      constraints: edge.constraints,
      router: { name: edge.router === 'normal' ? 'normal' : 'orth' },
      connector: { name: 'frade-rounded', args: { radius: 8 } },
      attrs: {
        line: {
          stroke: edge.bundle ? '#404040' : '#2563eb',
          strokeWidth: edge.bundle ? 1 : 2,
          ...edge.style,
          ...(edge.bundle ? { sourceMarker: null } : {}),
          targetMarker:
            edge.targetMarker === undefined
              ? edge.bundle
                ? null
                : { name: 'classic', size: 8 }
              : edge.targetMarker,
        },
      },
    })
  })
  const previous = graph.getCells(),
    zoom = graph.zoom(),
    translation = graph.translate()
  const historyEnabled = graph.isHistoryEnabled()
  graph.disableHistory()
  try {
    graph.resetCells([...nodes, ...edges], { documentRestore: true })
    graph.zoomTo(document.viewport?.zoom ?? 1)
    graph.translate(document.viewport?.pan.x ?? 0, document.viewport?.pan.y ?? 0)
    graph.cleanSelection()
    graph.cleanHistory()
  } catch (error) {
    graph.resetCells(previous, { documentRestore: true })
    graph.zoomTo(zoom)
    graph.translate(translation.tx, translation.ty)
    throw error
  } finally {
    if (historyEnabled) graph.enableHistory()
  }
  return document
}

import { test, expect, type Page } from '@playwright/test'
