declare global { interface Window { drawingProbe: { graph: Graph; session: DrawingSession } } }

async function probe(page: Page) {
  await page.goto('/editor-visual.html')
  await page.evaluate(async () => {
    const graphUrl='/src/editor/createGraph.ts', sessionUrl='/src/editor/drawingSession.ts'
    const {createGraph}=await import(graphUrl), {createDrawingSession}=await import(sessionUrl)
    const host=document.createElement('div')
    host.style.cssText='width:800px;height:500px;position:fixed;inset:0'
    document.body.append(host)
    const graph=createGraph(host)
    const session=createDrawingSession(graph,{format:'frade-draw',version:1,
      metadata:{id:'probe',name:'Probe'},graph:{nodes:[],edges:[]}}, {firstPageName:'Page-1'})
    window.drawingProbe={graph,session}
  })
}
