export type Point = { x: number; y: number }
export const diagramShapes = ['rect', 'rounded-rect', 'ellipse', 'diamond', 'text'] as const
export type DiagramShape = (typeof diagramShapes)[number]
export const styleKeys = [
  'fill',
  'stroke',
  'strokeWidth',
  'strokeDasharray',
  'opacity',
  'fillOpacity',
  'strokeOpacity',
  'rx',
  'ry',
  'fontSize',
  'fontFamily',
  'fontWeight',
  'fontStyle',
  'textAnchor',
] as const
export type DiagramStyle = Partial<Record<(typeof styleKeys)[number], string | number>>
export type Attachment = (
  { mode: 'floating'; nodeId: string } | { mode: 'fixed'; nodeId: string; portId: string }
) & { offset?: Point }
export type DiagramPort = Point & { id: string }
export type RepositoryNodeReference = { objectId: string; sourceId?: string }
export type DiagramShadow = { color: string; opacity: number; dx: number; dy: number; blur: number }
export type DiagramNode = {
  shadow?: DiagramShadow
  repositoryRef?: RepositoryNodeReference
  id: string
  shape: DiagramShape
  x: number
  y: number
  width: number
  height: number
  label: string
  style?: DiagramStyle
  labelStyle?: DiagramStyle
  ports?: DiagramPort[]
}
export type DiagramEdge = {
  labelPosition?: { distance: number; offset: Point }
  bundle?: { kind: 'empty'; integrationFlowRefs?: { repositoryId: string; objectId: string }[] }
  id: string
  source: Attachment
  target: Attachment
  constraints?: Array<{ axis: 'x' | 'y'; coordinate: number; order: number }>
  vertices?: Point[]
  style?: DiagramStyle
  router?: 'normal' | 'manhattan'
  targetMarker?: { name: 'classic' | 'block' | 'diamond' | 'circle'; size: number } | null
}
export interface DiagramDocument {
  format: 'frade-draw'
  version: 1
  metadata: { id: string; name: string }
  graph: { nodes: DiagramNode[]; edges: DiagramEdge[] }
  viewport?: { zoom: number; pan: Point }
}

function record(value: unknown, message: string): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(message)
  return value as Record<string, unknown>
}
function text(value: unknown, message: string): string {
  if (typeof value !== 'string' || !value.trim()) throw new Error(message)
  return value
}
function finite(value: unknown, message: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error(message)
  return value
}
function point(value: unknown, message: string): Point {
  const p = record(value, message)
  return { x: finite(p.x, message), y: finite(p.y, message) }
}
function style(value: unknown): DiagramStyle | undefined {
  if (value === undefined) return undefined
  const input = record(value, 'Invalid style'),
    result: DiagramStyle = {}
  for (const [key, val] of Object.entries(input)) {
    if (
      !(styleKeys as readonly string[]).includes(key) ||
      !(
        (typeof val === 'number' && Number.isFinite(val)) ||
        (typeof val === 'string' &&
          val.length <= 200 &&
          !/[<>\\]|url\s*\(|expression\s*\(/i.test(val))
      )
    ) {
      throw new Error('Invalid style')
    }
    result[key as (typeof styleKeys)[number]] = val as string | number
  }
  return result
}
function attachment(value: unknown): Attachment {
  const input = record(value, 'Invalid edge')
  const nodeId = text(input.nodeId, 'Invalid edge')
  let result: Attachment
  if (input.mode === 'floating') result = { mode: 'floating', nodeId }
  else if (input.mode === 'fixed')
    result = { mode: 'fixed', nodeId, portId: text(input.portId, 'Invalid edge') }
  else throw new Error('Invalid edge')
  if (input.offset !== undefined) result.offset = point(input.offset, 'Invalid terminal offset')
  return result
}

export function parseDocument(value: unknown): DiagramDocument {
  const input = record(value, 'Document must be an object')

  {label:t.sortPages,disabled:view.readOnly||view.pages.length<2,action:()=>session.sort(locale)},
  {label:t.deleteAll,disabled:view.readOnly,action:()=>session.clear(crypto.randomUUID(),numbered(1))},
]
  if(info.kind==='move')return view.pages.flatMap((p,i)=>p.id===info.id?[]:[{label:p.name,action:()=>session.move(info.id,i)}])
  if(!page)return []
  const duplicate={label:t.duplicateIt.replace('{1}',t.page),disabled:view.readOnly,
    action:()=>session.duplicate(page.id,crypto.randomUUID(),t.copyOf.replace('{1}',page.name))}
  const move={label:t.move,disabled:view.readOnly,submenu:true,action:(opener:HTMLElement)=>submenu(info,'move',opener)}
  const remove={label:t.removeIt.replace('{1}',t.page),disabled:view.readOnly,
    action:()=>session.remove(page.id,crypto.randomUUID(),numbered(1))}
  const renameItem={label:t.renameIt.replace('{1}',t.page)+'...',disabled:view.readOnly,dialog:true,
    action:()=>setRename({id:page.id,name:page.name,opener:tabs.current.get(page.id)!})}
  const separate={label:t.openInNewWindow,action:()=>onOpenPage(page.id)}
  if(info.kind==='current')return [renameItem,remove,...(view.pages.length>1?[move,null]:[]),duplicate,...(!embedded?[separate]:[])]
  return [
  ...(!embedded?[separate,null]:[]),duplicate,null,...(view.pages.length>1?[move]:[]),remove,renameItem,
]
}
const menus:MenuState[]=[]
for(let node=menu;node;node=node.parent)menus.unshift(node)
const control=(label:string,glyph:string,action:(opener:HTMLElement)=>void,disabled=false,hasMenu=false)=>
  <div role="button" className={'geTab geControlTab'+(disabled?' mxDisabled':'')}
    tabIndex={disabled?-1:0} title={label} aria-label={label} aria-disabled={disabled}
